const source = $json.body ?? $json;
const supplier = source.supplier ?? {};
const product = source.product ?? {};
const media = Array.isArray(source.media_urls) ? source.media_urls : [];
const evidence = Array.isArray(supplier.evidence_urls) ? supplier.evidence_urls : [];
const problems = [];

const text = (value) => typeof value === 'string' ? value.trim() : '';
const number = (value) => {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : null;
};
const https = (value) => /^https:\/\//i.test(text(value));

const requiredText = [
  ['supplier.name', supplier.name],
  ['supplier.product_url', supplier.product_url],
  ['product.title', product.title],
  ['product.product_type', product.product_type],
  ['product.sku', product.sku],
  ['product.currency', product.currency],
  ['product.fulfillment_method', product.fulfillment_method],
];
for (const [field, value] of requiredText) {
  if (!text(value)) problems.push(`${field}:missing`);
}

if (text(product.currency).toUpperCase() !== 'USD') problems.push('product.currency:must_be_USD');
if (!https(supplier.product_url)) problems.push('supplier.product_url:must_be_https');
if (evidence.length === 0 || evidence.some((url) => !https(url))) problems.push('supplier.evidence_urls:https_evidence_required');
if (supplier.terms_verified !== true) problems.push('supplier.terms_verified:required');
if (!text(supplier.terms_verified_at)) problems.push('supplier.terms_verified_at:required');

const unitCost = number(product.unit_cost);
const shippingCost = number(product.shipping_cost);
const retailPrice = number(product.retail_price);
const minDays = number(product.fulfillment_days_min);
const maxDays = number(product.fulfillment_days_max);
for (const [field, value] of [
  ['product.unit_cost', unitCost],
  ['product.shipping_cost', shippingCost],
  ['product.retail_price', retailPrice],
  ['product.fulfillment_days_min', minDays],
  ['product.fulfillment_days_max', maxDays],
]) {
  if (value === null || value < 0) problems.push(`${field}:invalid_number`);
}
if (minDays !== null && maxDays !== null && minDays > maxDays) problems.push('product.fulfillment_days:invalid_range');

const landedCost = unitCost !== null && shippingCost !== null ? unitCost + shippingCost : null;
const grossMargin = landedCost !== null && retailPrice !== null ? retailPrice - landedCost : null;
const marginRate = grossMargin !== null && retailPrice > 0 ? grossMargin / retailPrice : null;
if (landedCost !== null && retailPrice !== null && retailPrice <= landedCost) problems.push('pricing:no_positive_margin');
if (marginRate !== null && marginRate < 0.35) problems.push('pricing:margin_below_35_percent');

const readyForDraft = problems.length === 0;
const sampleVerified = source.sample_verified === true;
const mediaVerified = source.media_verified === true && media.length > 0 && media.every((url) => https(url));
const ownerPublishApproved = source.owner_publish_approved === true;
const publishEligible = readyForDraft && sampleVerified && mediaVerified && ownerPublishApproved;

return [{
  json: {
    workflow_contract: 'jbh-vendor-candidate-gate-v1',
    status: readyForDraft ? 'ready_for_shopify_draft' : 'blocked',
    ready_for_draft: readyForDraft,
    publish_eligible: publishEligible,
    blockers: problems,
    economics: {
      unit_cost: unitCost,
      shipping_cost: shippingCost,
      landed_cost: landedCost,
      retail_price: retailPrice,
      gross_margin: grossMargin,
      margin_rate: marginRate,
    },
    shopify_draft: readyForDraft ? {
      status: 'DRAFT',
      title: text(product.title),
      vendor: 'Juss Beautiful Hair',
      product_type: text(product.product_type),
      sku: text(product.sku),
      price: retailPrice,
      currency: 'USD',
      requires_shipping: true,
      source_supplier: text(supplier.name),
      source_product_url: text(supplier.product_url),
      evidence_urls: evidence,
      fulfillment_method: text(product.fulfillment_method),
      fulfillment_days_min: minDays,
      fulfillment_days_max: maxDays,
      media_urls: media.filter((url) => https(url)),
      publish_allowed: false
    } : null,
    gates: {
      supplier_terms_verified: supplier.terms_verified === true,
      sample_verified: sampleVerified,
      media_verified: mediaVerified,
      owner_publish_approved: ownerPublishApproved
    }
  }
}];

const result = $json;
return [{ json: {
  ok: result.ready_for_draft === true,
  status: result.status,
  blockers: result.blockers,
  economics: result.economics,
  shopify_draft: result.shopify_draft,
  publish_eligible: result.publish_eligible,
  activation_guard: 'This workflow prepares a draft payload only. It does not create or publish a Shopify product.',
  next_gate: result.ready_for_draft ? 'owner approval + credentialed Shopify draft writer' : 'repair candidate evidence and retry'
} }];
